namespace sv_ff693aaed12b48548809bf5be9fead19.Services;

/// <summary>
/// Scoped (per-circuit) service that polls for low-stock alerts and
/// notifies all subscribed components when new data arrives.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int CurrentLowStockCount { get; private set; }

    /// <summary>
    /// Raised on the calling (sync-context) thread whenever a new
    /// low-stock count is fetched, so subscribers can call StateHasChanged.
    /// </summary>
    public event Action? OnAlertCountChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
    }

    /// <summary>Simulates a database query – returns a random 0-15 count.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Ref-counted start: the first caller spins up the polling loop;
    /// subsequent callers just bump the count.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;
        if (_subscriberCount > 1)
            return;

        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    /// <summary>
    /// Ref-counted stop: only the last subscriber actually stops the loop.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount > 0)
            return;

        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    /// <summary>Fetches once immediately, then every tick.</summary>
    private async Task PollLoopAsync(CancellationToken ct)
    {
        await FetchAndNotifyAsync();

        try
        {
            while (_timer is not null && await _timer.WaitForNextTickAsync(ct))
            {
                await FetchAndNotifyAsync();
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on StopPolling / Dispose.
        }
    }

    private async Task FetchAndNotifyAsync()
    {
        CurrentLowStockCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        OnAlertCountChanged?.Invoke();
    }

    public void Dispose()
    {
        _subscriberCount = 0;
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();
    }
}

