@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title text-muted">Current Warehouse</h5>
                <p class="display-6">@CurrentWarehouseName</p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title text-muted">Low-Stock Alerts</h5>
                <p class="display-6">
                    @if (AlertService.CurrentLowStockCount > 0)
                    {
                        <span class="text-danger">⚠ @AlertService.CurrentLowStockCount items</span>
                    }
                    else
                    {
                        <span class="text-success">✓ All stocked</span>
                    }
                </p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title text-muted">Polling Status</h5>
                <p class="display-6 text-info">● Live</p>
                <small class="text-muted">Refreshes every 10 s</small>
            </div>
        </div>
    </div>
</div>

@code {
    private string CurrentWarehouseName =>
        WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId).Name
        ?? WarehouseState.CurrentWarehouseId;

    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += OnWarehouseChanged;
        AlertService.OnAlertCountChanged += OnAlertCountChanged;
        AlertService.StartPolling();
    }

    private void OnWarehouseChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private void OnAlertCountChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= OnWarehouseChanged;
        AlertService.OnAlertCountChanged -= OnAlertCountChanged;
        AlertService.StopPolling();
    }
}

